      "interviewBlueprint": {
        "questionIntent": "느린 신고 목록 조회 쿼리에서 조회 조건과 실행 계획을 바탕으로 인덱스에 넣을 열을 판단했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
