        "excellent": {
          "criteria": [
            "신고 목록 조회 쿼리의 실제 조회 조건이나 실행 계획을 짚으며, 특정 열을 인덱스에 넣은 이유를 구체적으로 설명한다.",
            "선택한 열이 어떤 조회 작업을 줄일 것으로 보았는지 연결해 설명하며, 인덱스를 추가했다는 지원서 내용의 반복에 그치지 않는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 조회 쿼리에서 조건에 자주 쓰는 열에 인덱스를 둔다는 일반적인 원칙은 말하지만, 당시 열 선택과 연결되는 구체적인 설명은 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 조회 쿼리의 인덱스 열 선택 이유를 설명하지 못하거나, 조회 시간 단축 수치 등 다른 이야기만 한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "알림 중복 발송 오류에서 로그의 어떤 단서를 통해 최초 추정을 수정하고 서버 측 원인으로 범위를 좁혔는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받고 처음에는 클라이언트 문제를 의심했다.",
          "task": "로그를 살펴 중복 발송의 원인이 어디에 있는지 좁혀야 했다.",
          "action": "로그에서 발견한 단서와 그 단서가 클라이언트 문제라는 추정을 바꾼 이유를 설명한다.",
          "result": "스케줄러가 서버 두 대에서 동시에 실행된 것으로 원인을 좁힌 판단에 초점을 맞춘다."
        },
        "expectedEvidence": [
          "클라이언트 문제라는 추정을 서버 측 문제로 바꾸게 한 구체적인 로그 단서",
          "시간순으로 살핀 로그에서 서로 연결해 본 실행 기록",
          "그 기록이 서버 측 중복 실행을 가리킨다고 해석한 이유"
        ]
      },
      "question": "포켓마켓에서 알림 중복 발송을 처음에는 클라이언트 문제로 의심했을 때, 서버 쪽 문제로 판단을 바꾸게 한 로그의 단서는 무엇이었나요?",
      "answerTip": "정확한 문구가 기억나지 않으면 당시 상황을 풀어서 답해도 됩니다.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 중복 발송 로그에서 연결해 본 실행 기록을 시간 관계나 서버 구분 등 당시 확인한 특징으로 구체적으로 설명한다.",
            "그 로그 단서가 클라이언트 문제가 아닌 서버 측 중복 실행을 가리킨다고 판단한 이유를 설명하며, 서버 두 대에서 실행됐다는 결론만 반복하지 않는다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 중복 발송 로그에서 중복 실행을 확인했다고 설명하지만, 판단을 바꾸게 한 기록의 특징은 일반적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송의 원인을 좁힌 로그 단서를 제시하지 못하거나, 잠금 적용이나 배포 체크리스트 등 수정 이후의 이야기만 한다."
          ]
        }
      }
    }
  ]
}

